-- Standard "Seller nurture" workflow: 8 emails over 8 weeks to a new seller
-- lead (MREA's 8x8), in the agent's name, replies go to the agent. Stops when
-- the lead books or signs, or is marked Lost or Invalid Number. If they open
-- the "what your home could be worth" or "free valuation" email, the agent gets a
-- WhatsApp to call. Emails only go out in the daytime (quiet hours), and every
-- one carries the unsubscribe link.
-- New leads only (it starts when a lead comes in). Added to every account
-- switched OFF: the team switches it on per account in Automations.
insert into public.workflows (agent_id, is_template, name, published, standard, standard_on, definition)
select null, true, 'Seller nurture — 8 emails in 8 weeks', false, true, false, '{"trigger":{"kind":"lead_created"},"filters":[{"field":"has_email","value":"yes"},{"field":"pipeline","value":"Sellers"}],"steps":[{"id":"nurw1","type":"wait","amount":1,"unit":"days"},{"id":"nure2","type":"email_lead","subject":"Two quick questions about your home, {{first_name}}","body":"Hi {{first_name}},\n\nI''m working on your home evaluation and want to get the numbers right. Two quick questions:\n\n1. Have you done any renovations or upgrades?\n2. Roughly when would you like to move?\n\nJust reply to this email, or WhatsApp me if that''s easier: {{whatsapp_link}}\n\n{{agent_name}}\n{{agent_phone}}"},{"id":"nurw3","type":"wait","amount":2,"unit":"days"},{"id":"nure4","type":"email_lead","subject":"What your home could be worth, {{first_name}}","body":"Hi {{first_name}},\n\n{{recent_sales}}\n\nEvery street is different, so the best guide to what your home is worth is a proper evaluation. If you''d like a figure for {{address}}, just reply and I''ll put it together.\n\n{{agent_name}}\n{{agent_phone}}"},{"id":"nurw5","type":"wait","amount":1,"unit":"days"},{"id":"nurb6","type":"branch","check":"opened_last_email","value":"","yes":[{"id":"nurm7","type":"whatsapp_agent","text":"{{first_name}} just opened your email about what their home could be worth. Good moment to call: {{action_link}}"}],"no":[]},{"id":"nurw8","type":"wait","amount":3,"unit":"days"},{"id":"nure9","type":"email_lead","subject":"3 things that cost sellers money","body":"Hi {{first_name}},\n\nMost of the money sellers lose comes from three avoidable things:\n\n1. Starting at too high a price. The home sits, buyers start asking what''s wrong with it, and it ends up selling for less than it would have.\n2. Choosing the agent with the highest valuation. A high number wins the listing, not the sale.\n3. Leaving the paperwork for later. Compliance certificates (electrical, and sometimes gas, electric fence or beetle) can hold up transfer if they''re only sorted at the end.\n\nIf you''d like, I can tell you what your home is realistically worth and what to get ready. No pressure either way.\n\n{{agent_name}}\n{{agent_phone}}"},{"id":"nurw10","type":"wait","amount":7,"unit":"days"},{"id":"nure11","type":"email_lead","subject":"Still thinking of selling, {{first_name}}?","body":"Hi {{first_name}},\n\nAre you still thinking of selling this year, or have your plans changed?\n\nA one-word reply is perfect.\n\n{{agent_name}}\n{{agent_phone}}"},{"id":"nurw12","type":"wait","amount":7,"unit":"days"},{"id":"nure13","type":"email_lead","subject":"What it really costs to sell your home","body":"Hi {{first_name}},\n\nA question I get a lot: \"What will I actually walk away with?\" The main costs when you sell in South Africa are:\n\n- The agent''s commission (plus VAT)\n- Bond cancellation: your bank needs 90 days'' notice, or it can charge a penalty, and there are attorney fees to cancel the bond\n- Compliance certificates, like the electrical certificate\n- Capital gains tax, but only if it isn''t your main home\n\nIf you''d like, I can work out a rough figure of what you''d take home from {{address}}. Just reply.\n\n{{agent_name}}\n{{agent_phone}}"},{"id":"nurw14","type":"wait","amount":9,"unit":"days"},{"id":"nure15","type":"email_lead","subject":"A valuation, without the pressure","body":"Hi {{first_name}},\n\nSome people put off a valuation because they think it means they have to sell. It doesn''t.\n\nA valuation from me is free and comes with no obligation. You get a realistic price range based on what''s actually sold near you, and you can do whatever you like with it, including nothing.\n\nWould a 15-minute chat this week suit you? Reply with a day and I''ll call you then.\n\n{{agent_name}}\n{{agent_phone}}"},{"id":"nurw16","type":"wait","amount":1,"unit":"days"},{"id":"nurb17","type":"branch","check":"opened_last_email","value":"","yes":[{"id":"nurm18","type":"whatsapp_agent","text":"{{first_name}} just opened your email about a free valuation. Good moment to call: {{action_link}}"}],"no":[]},{"id":"nurw19","type":"wait","amount":11,"unit":"days"},{"id":"nure20","type":"email_lead","subject":"Your home''s value today, {{first_name}}","body":"Hi {{first_name}},\n\nPrices near you keep moving.\n\n{{recent_sales}}\n\nIf you''re curious what {{address}} could sell for today, I''m happy to tell you.\n\n{{agent_name}}\n{{agent_phone}}"},{"id":"nurw21","type":"wait","amount":14,"unit":"days"},{"id":"nure22","type":"email_lead","subject":"Should I close your file, {{first_name}}?","body":"Hi {{first_name}},\n\nI haven''t heard back, so I''m guessing selling isn''t a priority right now. That''s completely fine.\n\nShould I close your file, or would you still like your home evaluation? Just reply \"close\" or \"keep\".\n\nEither way, I''m here when you''re ready.\n\n{{agent_name}}\n{{agent_phone}}"}],"exits":[{"kind":"booked","on":true},{"kind":"lost","on":true},{"kind":"any_stage_change","on":false}],"settings":{"quietHours":true,"reEnter":false}}'::jsonb
where not exists (select 1 from public.workflows w where w.is_template and w.name = 'Seller nurture — 8 emails in 8 weeks');

select public.add_standard_workflows(agent_id) from public.agent_profiles;
